{"type":"agent_end","messages":[{"role":"user","content":[{"type":"text","text":"{\"schema\": \"aos-material-review/v1\", \"request_id\": \"qyh-restored-host-preflight-adapter-20261013-r1\", \"task_id\": \"qyh-restored-host-preflight-adapter-20261013\", \"owner\": \"codex-01a107a2-e9e4-7670-bc44-1144fa9b27e2\", \"kind\": \"quality\", \"baseline\": {\"head\": \"a9a7cb68c86914532a791ad73674597d428d0a13\", \"authority_revision\": \"AOS-001990\", \"files\": {\".evidence/qyh-restored-host-preflight-adapter-20261013/review-material-0.txt\": \"7918751d9976f45997768c9aa7b66ca7b974ba10e5775056bc25b18ca39839eb\", \".evidence/qyh-restored-host-preflight-adapter-20261013/review-material-1.txt\": \"b4a5258bc8889586deeb69885432194add97c8f1a7e4614f8327ab8b500ec91c\", \".evidence/qyh-restored-host-preflight-adapter-20261013/review-material-2.txt\": \"3b2044197c4b55874fb706b116c6820f20c1938fe5281319351b262148c20e1a\", \".evidence/qyh-restored-host-preflight-adapter-20261013/review-material-3.txt\": \"76c1fe7b3dfc6604262a07ffe9f27655d8dc397d2426c4c232159ce967b9717a\"}}, \"claims\": [\"Restored preparation explicitly reuses the existing exact installation reader and the shared isolated identity gate.\", \"Historical signed preflight behavior remains delegated to the same original signed reader and identity checks.\", \"Explicit invalid or mixed restored inputs do not fall back to the historical route or admit FULL mode.\", \"This patch provides readonly preflight only and neither wires production startup nor proves eight workbenches restored.\"], \"materials\": {\".evidence/qyh-restored-host-preflight-adapter-20261013/review-material-0.txt\": \"#!/usr/bin/env python3\\n\\\"\\\"\\\"Read-only cross-check of the current signed installation and Host identities.\\n\\nThis command never selects or starts a Runtime Host.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport argparse\\nimport importlib.util\\nimport json\\nimport os\\nimport sys\\nfrom pathlib import Path\\n\\nimport psycopg\\nfrom psycopg.conninfo import conninfo_to_dict\\nfrom psycopg.rows import dict_row\\n\\n\\nROOT = Path(__file__).resolve().parents[1]\\n# Importing the runtime package can construct the API app. Keep this dedicated\\n# preflight independent of the repository's development .env and its secrets.\\nos.environ[\\\"AOS_DOTENV_DISABLED\\\"] = \\\"1\\\"\\nsys.path.insert(0, str(ROOT / \\\"services/aos-api\\\"))\\n\\nfrom aos_api.extension_runtime.production_runtime import _PROTECTED_RELATIONS\\nfrom aos_api.extension_runtime.runtime_configuration_candidates import read_candidates\\nfrom aos_api.extension_runtime.runtime_connections import _runtime_file_dsns\\nfrom aos_api.extension_runtime.runtime_identity import (\\n    probe_runtime_database_identity, require_isolated_runtime_identities,\\n)\\nfrom aos_api.tenant_scope import TenantScope\\n\\n\\nclass HostPreflightBlocked(RuntimeError):\\n    pass\\n\\n\\ndef _load_signed_preflight():\\n    spec = importlib.util.spec_from_file_location(\\n        \\\"current_signed_preview\\\", ROOT / \\\"scripts/a0v_current_preview_http.py\\\")\\n    if spec is None or spec.loader is None:\\n        raise HostPreflightBlocked(\\\"SIGNED_PREFLIGHT_UNAVAILABLE\\\")\\n    module = importlib.util.module_from_spec(spec)\\n    spec.loader.exec_module(module)\\n    return module.preflight\\n\\n\\nsigned_preflight = _load_signed_preflight()\\n\\n\\ndef _load_restored_preflight():\\n    # Use the existing preserved-volume and exact signed release reader, not the\\n    # active-generation image reader: preparation precedes installation apply.\\n    sys.path.insert(0, str(ROOT / 'scripts'))\\n    import a0v_qyh_restored_http\\n    return a0v_qyh_restored_http\\n\\n\\ndef preflight_restored(*, identity_file: Path, installation_id: str,\\n                      bundle_root: Path, trust_roots_file: Path,\\n                      credential_file: Path, preparation_only: bool = False):\\n    if preparation_only is not True:\\n        raise HostPreflightBlocked('RESTORED_PREPARATION_ONLY_REQUIRED')\\n    if (any(not isinstance(path, Path) or not path.is_absolute() for path in\\n            (identity_file, bundle_root, trust_roots_file, credential_file))\\n            or type(installation_id) is not str or not installation_id):\\n        raise HostPreflightBlocked('RESTORED_PREFLIGHT_INPUT_INVALID')\\n    try:\\n        restored = _load_restored_preflight()\\n        report = restored.select_current_installation(\\n            identity_file=identity_file, installation_id=installation_id,\\n            bundle_root=bundle_root, trust_roots_file=trust_roots_file)\\n        selected = report['currentInstallation']\\n        if (report['identity']['database'] != 'aos_meta_head'\\n                or selected['installationId'] != installation_id\\n                or selected['authorization'] != 'CURRENT_INSTALLATION_EVIDENCE_ONLY_NO_START'\\n                or selected['runtimeHostEnabled'] is not False\\n                or selected['apiStartAuthorized'] is not False):\\n            raise ValueError('current restored evidence differs')\\n        identity = restored._identity_parameters(identity_file)\\n        parameters = {key: identity[key] for key in ('host', 'port', 'dbname', 'user')}\\n        parameters['passfile'] = identity['pgpassFile']\\n        if parameters['dbname'] != report['identity']['database']:\\n            raise ValueError('current restored database differs')\\n        signed = {'database': parameters['dbname'], 'installationId': selected['installationId'],\\n                  'signedRoot': str(bundle_root.resolve(strict=True)),\\n                  'trustRoots': str(trust_roots_file.resolve(strict=True))}\\n    except Exception:\\n        raise HostPreflightBlocked('RESTORED_INSTALLATION_INVALID') from None\\n    return _preflight_identities(parameters=parameters, signed=signed,\\n                                credential_file=credential_file, preparation_only=True)\\n\\n\\ndef require_current_dsn_targets(dsns: dict[str, str], target: str) -> None:\\n    if set(dsns) != {\\\"directory\\\", \\\"runtime\\\", \\\"web\\\"}:\\n        raise HostPreflightBlocked(\\\"CREDENTIAL_FILE_INVALID\\\")\\n    try:\\n        databases = {plane: conninfo_to_dict(dsn).get(\\\"dbname\\\") for plane, dsn in dsns.items()}\\n    except Exception:\\n        raise HostPreflightBlocked(\\\"CREDENTIAL_FILE_INVALID\\\") from None\\n    if any(database != target for database in databases.values()):\\n        raise HostPreflightBlocked(\\\"CREDENTIAL_DATABASE_DRIFT\\\")\\n\\n\\ndef require_current_identities(*, directory, runtime, web, authority) -> None:\\n    try:\\n        require_isolated_runtime_identities(directory=directory, runtime=runtime, web=web)\\n        if directory.authority != authority:\\n            raise RuntimeError(\\\"current signed database authority differs\\\")\\n    except Exception:\\n        raise HostPreflightBlocked(\\\"RUNTIME_IDENTITY_INVALID\\\") from None\\n\\n\\ndef require_current_host_and_candidates(\\n    conn, directory, *, preparation_only: bool = False,\\n) -> dict[str, object]:\\n    if type(preparation_only) is not bool:\\n        raise HostPreflightBlocked(\\\"ADMISSION_MODE_INVALID\\\")\\n    row = conn.execute(\\n        \\\"\\\"\\\"SELECT a.state,a.host_id,i.database_role::text AS database_role,\\n                  i.database_role_oid,i.enabled\\n             FROM extension_runtime_host_assignment a\\n             LEFT JOIN extension_runtime_host_identity i ON i.host_id=a.host_id\\n            WHERE a.org_id=%s AND a.project_id=%s\\\"\\\"\\\",\\n        (\\\"org-org\\\", \\\"dev-project\\\"),\\n    ).fetchone()\\n    if row is None or row[\\\"state\\\"] != \\\"assigned\\\" or not row[\\\"host_id\\\"]:\\n        raise HostPreflightBlocked(\\\"HOST_ASSIGNMENT_MISSING\\\")\\n    if (row[\\\"enabled\\\"] is not True or row[\\\"database_role\\\"] != directory.session_user\\n            or row[\\\"database_role_oid\\\"] != directory.role_oid):\\n        raise HostPreflightBlocked(\\\"HOST_IDENTITY_MISMATCH\\\")\\n    if preparation_only:\\n        existing = conn.execute(\\n            \\\"\\\"\\\"SELECT count(*) AS enabled_bindings FROM extension_runtime_binding\\n                WHERE org_id=%s AND project_id=%s AND enabled\\\"\\\"\\\",\\n            (\\\"org-org\\\", \\\"dev-project\\\"),\\n        ).fetchone()\\n        if (existing is None or type(existing[\\\"enabled_bindings\\\"]) is not int\\n                or existing[\\\"enabled_bindings\\\"] != 0):\\n            raise HostPreflightBlocked(\\\"ACTIVE_BINDING_REQUIRES_FULL_HOST\\\")\\n    candidates = read_candidates(conn, TenantScope(org_id=\\\"org-org\\\", project_id=\\\"dev-project\\\"))\\n    if not candidates.all_present and not preparation_only:\\n        raise HostPreflightBlocked(\\\"CONFIGURATION_CANDIDATES_MISSING\\\")\\n    return {\\\"hostId\\\": row[\\\"host_id\\\"], \\\"candidateCounts\\\": candidates.counts,\\n            \\\"admissionMode\\\": \\\"PREPARATION_ONLY\\\" if preparation_only else \\\"FULL\\\"}\\n\\n\\ndef preflight(*, signed_receipt: Path, credential_file: Path | None,\\n              preparation_only: bool = False) -> dict[str, object]:\\n    if type(preparation_only) is not bool:\\n        raise HostPreflightBlocked(\\\"ADMISSION_MODE_INVALID\\\")\\n    if credential_file is None:\\n        raise HostPreflightBlocked(\\\"CREDENTIAL_FILE_REQUIRED\\\")\\n    if not credential_file.is_absolute():\\n        raise HostPreflightBlocked(\\\"CREDENTIAL_FILE_INVALID\\\")\\n    try:\\n        parameters, signed = signed_preflight(signed_receipt=signed_receipt)\\n    except Exception:\\n        raise HostPreflightBlocked(\\\"SIGNED_INSTALLATION_INVALID\\\") from None\\n    return _preflight_identities(parameters=parameters, signed=signed,\\n                                credential_file=credential_file, preparation_only=preparation_only)\\n\\n\\ndef _preflight_identities(*, parameters, signed, credential_file, preparation_only):\\n    \\\"\\\"\\\"One unchanged database identity/admission gate for either signed reader.\\\"\\\"\\\"\\n    try:\\n        dsns, credential_generation = _runtime_file_dsns(\\n            credential_file, with_generation=True)\\n    except Exception:\\n        raise HostPreflightBlocked(\\\"CREDENTIAL_FILE_INVALID\\\") from None\\n    require_current_dsn_targets(dsns, signed[\\\"database\\\"])\\n    try:\\n        with psycopg.connect(**parameters, row_factory=dict_row) as current:\\n            current.read_only = True\\n            authority_row = current.execute(\\n                \\\"\\\"\\\"SELECT coalesce(inet_server_addr()::text,'local') AS server_addr,\\n                          inet_server_port() AS server_port,current_database() AS database_name\\\"\\\"\\\"\\n            ).fetchone()\\n            authority = (authority_row[\\\"server_addr\\\"], authority_row[\\\"server_port\\\"] or 0,\\n                         authority_row[\\\"database_name\\\"])\\n            if authority[2] != signed[\\\"database\\\"]:\\n                raise HostPreflightBlocked(\\\"SIGNED_DATABASE_DRIFT\\\")\\n            with psycopg.connect(dsns[\\\"directory\\\"], row_factory=dict_row) as directory_conn:\\n                directory_conn.read_only = True\\n                directory = probe_runtime_database_identity(\\n                    directory_conn, protected_relations=_PROTECTED_RELATIONS)\\n                with psycopg.connect(dsns[\\\"runtime\\\"], row_factory=dict_row) as runtime_conn:\\n                    runtime_conn.read_only = True\\n                    runtime = probe_runtime_database_identity(\\n                        runtime_conn, protected_relations=_PROTECTED_RELATIONS)\\n                    with psycopg.connect(dsns[\\\"web\\\"], row_factory=dict_row) as web_conn:\\n                        web_conn.read_only = True\\n                        web = probe_runtime_database_identity(\\n                            web_conn, protected_relations=_PROTECTED_RELATIONS)\\n                require_current_identities(directory=directory, runtime=runtime,\\n                                           web=web, authority=authority)\\n                host = require_current_host_and_candidates(\\n                    current, directory, preparation_only=preparation_only)\\n    except HostPreflightBlocked:\\n        raise\\n    except Exception:\\n        raise HostPreflightBlocked(\\\"DATABASE_PREFLIGHT_FAILED\\\") from None\\n    try:\\n        _, current_generation = _runtime_file_dsns(credential_file, with_generation=True)\\n        if current_generation != credential_generation:\\n            raise HostPreflightBlocked(\\\"CREDENTIAL_FILE_CHANGED\\\")\\n    except HostPreflightBlocked:\\n        raise\\n    except Exception:\\n        raise HostPreflightBlocked(\\\"CREDENTIAL_FILE_CHANGED\\\") from None\\n    return {\\\"outcome\\\": \\\"CURRENT_SIGNED_HOST_READONLY_PREFLIGHT_GREEN\\\",\\n            \\\"database\\\": signed[\\\"database\\\"], \\\"installationId\\\": signed[\\\"installationId\\\"],\\n            \\\"databaseAuthority\\\": list(authority),\\n            \\\"signedRoot\\\": signed[\\\"signedRoot\\\"], \\\"trustRoots\\\": signed[\\\"trustRoots\\\"],\\n            \\\"credentialFileGeneration\\\": credential_generation,\\n            \\\"scope\\\": [\\\"org-org\\\", \\\"dev-project\\\"], **host,\\n            \\\"authorization\\\": \\\"PREFLIGHT_ONLY_NO_RUNTIME_START\\\"}\\n\\n\\ndef main() -> int:\\n    parser = argparse.ArgumentParser()\\n    parser.add_argument(\\\"--signed-receipt\\\", type=Path)\\n    parser.add_argument(\\\"--credential-file\\\", type=Path)\\n    parser.add_argument(\\\"--preparation-only\\\", action=\\\"store_true\\\")\\n    parser.add_argument('--restored-api-identity', type=Path)\\n    parser.add_argument('--restored-installation')\\n    parser.add_argument('--bundle-root', type=Path)\\n    parser.add_argument('--trust-roots-file', type=Path)\\n    args = parser.parse_args()\\n    restored_values = (args.restored_api_identity, args.restored_installation,\\n                       args.bundle_root, args.trust_roots_file)\\n    if any(value is not None for value in restored_values):\\n        if (args.signed_receipt is not None or any(value is None for value in restored_values)\\n                or args.credential_file is None or not args.preparation_only):\\n            parser.error('restored preparation requires all exact inputs and no historical signed receipt')\\n    elif args.signed_receipt is None:\\n        parser.error('signed receipt or explicit restored preparation inputs required')\\n    try:\\n        if args.restored_api_identity is not None:\\n            result = preflight_restored(identity_file=args.restored_api_identity,\\n                installation_id=args.restored_installation, bundle_root=args.bundle_root,\\n                trust_roots_file=args.trust_roots_file, credential_file=args.credential_file,\\n                preparation_only=args.preparation_only)\\n        else:\\n            result = preflight(signed_receipt=args.signed_receipt,\\n                               credential_file=args.credential_file,\\n                               preparation_only=args.preparation_only)\\n        print(json.dumps(result, sort_keys=True))\\n        return 0\\n    except HostPreflightBlocked as exc:\\n        print(json.dumps({\\\"outcome\\\": \\\"SAFE_BLOCKED\\\", \\\"reasonCode\\\": str(exc)}, sort_keys=True))\\n        return 2\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    raise SystemExit(main())\\n\", \".evidence/qyh-restored-host-preflight-adapter-20261013/review-material-1.txt\": \"import importlib.util\\nfrom pathlib import Path\\n\\nimport pytest\\n\\nfrom aos_api.extension_runtime.runtime_identity import RuntimeDatabaseIdentity\\n\\n\\nSCRIPT = Path(__file__).resolve().parents[4] / \\\"scripts/a0v_current_runtime_host_preflight.py\\\"\\n\\n\\ndef restored_arguments():\\n    return dict(identity_file=Path('/protected/restored.json'),\\n                installation_id='ab2fd72f-d81c-400d-bbbc-e1589a159d6b',\\n                bundle_root=Path('/signed/restored'),\\n                trust_roots_file=Path('/signed/roots.json'),\\n                credential_file=Path('/protected/planes.json'), preparation_only=True)\\n\\n\\ndef test_restored_preflight_never_admits_full_mode(gate):\\n    args = restored_arguments()\\n    args['preparation_only'] = False\\n    with pytest.raises(gate.HostPreflightBlocked, match='RESTORED_PREPARATION_ONLY_REQUIRED'):\\n        gate.preflight_restored(**args)\\n\\n\\n@pytest.mark.parametrize('field', ['identity_file', 'bundle_root', 'trust_roots_file', 'credential_file'])\\ndef test_restored_preflight_requires_absolute_inputs(gate, field):\\n    args = restored_arguments()\\n    args[field] = Path('relative.json')\\n    with pytest.raises(gate.HostPreflightBlocked, match='RESTORED_PREFLIGHT_INPUT_INVALID'):\\n        gate.preflight_restored(**args)\\n\\n\\ndef test_restored_preflight_reuses_exact_selector_and_shared_identity_gate(gate, monkeypatch, tmp_path):\\n    args = restored_arguments()\\n    args['bundle_root'] = tmp_path / 'signed'\\n    args['bundle_root'].mkdir()\\n    args['trust_roots_file'] = tmp_path / 'roots.json'\\n    args['trust_roots_file'].write_text('{}')\\n    calls = []\\n    class Restored:\\n        @staticmethod\\n        def select_current_installation(**kwargs):\\n            calls.append(kwargs)\\n            return {'identity': {'database': 'aos_meta_head'},\\n                    'currentInstallation': {'installationId': args['installation_id'],\\n                        'authorization': 'CURRENT_INSTALLATION_EVIDENCE_ONLY_NO_START',\\n                        'runtimeHostEnabled': False, 'apiStartAuthorized': False}}\\n        @staticmethod\\n        def _identity_parameters(path):\\n            assert path == args['identity_file']\\n            return {'host': '127.0.0.1', 'port': 18446, 'dbname': 'aos_meta_head',\\n                    'user': 'limited', 'pgpassFile': '/protected/passfile'}\\n    monkeypatch.setattr(gate, '_load_restored_preflight', lambda: Restored)\\n    def identities(**kwargs):\\n        assert kwargs['parameters']['passfile'] == '/protected/passfile'\\n        assert 'pgpassFile' not in kwargs['parameters']\\n        assert kwargs['signed'] == {'database': 'aos_meta_head',\\n            'installationId': args['installation_id'], 'signedRoot': str(args['bundle_root']),\\n            'trustRoots': str(args['trust_roots_file'])}\\n        assert kwargs['credential_file'] == args['credential_file']\\n        assert kwargs['preparation_only'] is True\\n        return {'outcome': 'CURRENT_SIGNED_HOST_READONLY_PREFLIGHT_GREEN'}\\n    monkeypatch.setattr(gate, '_preflight_identities', identities)\\n    assert gate.preflight_restored(**args)['outcome'] == 'CURRENT_SIGNED_HOST_READONLY_PREFLIGHT_GREEN'\\n    assert calls == [{k: args[k] for k in ('identity_file', 'installation_id', 'bundle_root', 'trust_roots_file')}]\\n\\n\\ndef test_restored_selector_failure_has_no_legacy_fallback_or_identity_probe(gate, monkeypatch):\\n    class Restored:\\n        @staticmethod\\n        def select_current_installation(**_):\\n            raise ValueError('sensitive failure details')\\n    monkeypatch.setattr(gate, '_load_restored_preflight', lambda: Restored)\\n    monkeypatch.setattr(gate, 'signed_preflight', lambda **_: pytest.fail('legacy fallback'))\\n    monkeypatch.setattr(gate, '_runtime_file_dsns', lambda *_a, **_k: pytest.fail('identity probe'))\\n    with pytest.raises(gate.HostPreflightBlocked, match='RESTORED_INSTALLATION_INVALID') as exc:\\n        gate.preflight_restored(**restored_arguments())\\n    assert 'sensitive' not in str(exc.value)\\n\\n\\n@pytest.mark.parametrize('change', ['database', 'installation', 'authorization', 'start'])\\ndef test_restored_rejects_altered_reader_authority_before_identity_probe(gate, monkeypatch, change):\\n    args = restored_arguments()\\n    class Restored:\\n        @staticmethod\\n        def select_current_installation(**_):\\n            result = {'identity': {'database': 'aos_meta_head'},\\n                'currentInstallation': {'installationId': args['installation_id'],\\n                    'authorization': 'CURRENT_INSTALLATION_EVIDENCE_ONLY_NO_START',\\n                    'runtimeHostEnabled': False, 'apiStartAuthorized': False}}\\n            if change == 'database': result['identity']['database'] = 'other_database'\\n            if change == 'installation': result['currentInstallation']['installationId'] = 'other'\\n            if change == 'authorization': result['currentInstallation']['authorization'] = 'START'\\n            if change == 'start': result['currentInstallation']['runtimeHostEnabled'] = True\\n            return result\\n    monkeypatch.setattr(gate, '_load_restored_preflight', lambda: Restored)\\n    monkeypatch.setattr(gate, '_runtime_file_dsns', lambda *_a, **_k: pytest.fail('identity probe'))\\n    with pytest.raises(gate.HostPreflightBlocked, match='RESTORED_INSTALLATION_INVALID'):\\n        gate.preflight_restored(**args)\\n\\n\\n@pytest.mark.parametrize('argv', [\\n    ['--restored-api-identity', '/protected/restored.json'],\\n    ['--signed-receipt', '/signed/receipt', '--restored-api-identity', '/protected/restored.json'],\\n    ['--restored-api-identity', '/protected/restored.json', '--restored-installation', 'current',\\n     '--bundle-root', '/signed/root', '--trust-roots-file', '/signed/roots',\\n     '--credential-file', '/protected/planes'],\\n])\\ndef test_cli_rejects_partial_mixed_or_nonpreparation_restored_route(gate, monkeypatch, argv):\\n    import sys\\n    monkeypatch.setattr(sys, 'argv', ['gate', *argv])\\n    monkeypatch.setattr(gate, 'preflight', lambda **_: pytest.fail('legacy fallback'))\\n    monkeypatch.setattr(gate, 'preflight_restored', lambda **_: pytest.fail('restored called'))\\n    with pytest.raises(SystemExit) as exc:\\n        gate.main()\\n    assert exc.value.code == 2\\n\\n\\n@pytest.fixture\\ndef gate():\\n    spec = importlib.util.spec_from_file_location(\\\"a0v_current_runtime_host_preflight\\\", SCRIPT)\\n    module = importlib.util.module_from_spec(spec)\\n    assert spec.loader is not None\\n    spec.loader.exec_module(module)\\n    return module\\n\\n\\ndef identity(role, oid, *, database=\\\"aos_current_preview_20260927\\\", directory=False,\\n             runtime=False, privileged=False):\\n    return RuntimeDatabaseIdentity(\\n        authority=(\\\"172.0.0.2\\\", 5432, database), session_user=role, role_oid=oid,\\n        directory_member=directory, runtime_member=runtime, privileged=privileged,\\n        owns_protected_relation=False,\\n    )\\n\\n\\ndef test_missing_credentials_fail_before_signed_or_database_access(gate, monkeypatch):\\n    monkeypatch.setattr(gate, \\\"signed_preflight\\\", lambda **_: pytest.fail(\\\"signed preflight ran\\\"))\\n    with pytest.raises(gate.HostPreflightBlocked, match=\\\"CREDENTIAL_FILE_REQUIRED\\\"):\\n        gate.preflight(signed_receipt=Path(\\\"/unused\\\"), credential_file=None)\\n\\n\\ndef test_old_database_dsn_rejected_before_connection(gate):\\n    dsns = {plane: f\\\"host=localhost dbname=aos_meta_head user={plane}\\\"\\n            for plane in (\\\"directory\\\", \\\"runtime\\\", \\\"web\\\")}\\n    with pytest.raises(gate.HostPreflightBlocked, match=\\\"CREDENTIAL_DATABASE_DRIFT\\\"):\\n        gate.require_current_dsn_targets(dsns, \\\"aos_current_preview_20260927\\\")\\n\\n\\ndef test_signed_receipt_failure_rejected_before_credential_read(gate, monkeypatch):\\n    monkeypatch.setattr(gate, \\\"signed_preflight\\\", lambda **_: (_ for _ in ()).throw(ValueError(\\\"bad\\\")))\\n    monkeypatch.setattr(gate, \\\"_runtime_file_dsns\\\", lambda *_: pytest.fail(\\\"credential file read\\\"))\\n    with pytest.raises(gate.HostPreflightBlocked, match=\\\"SIGNED_INSTALLATION_INVALID\\\"):\\n        gate.preflight(signed_receipt=Path(\\\"/invalid\\\"), credential_file=Path(\\\"/protected/current.json\\\"))\\n\\n\\ndef test_old_database_credential_rejected_before_identity_connection(gate, monkeypatch):\\n    monkeypatch.setattr(gate, \\\"signed_preflight\\\", lambda **_: (\\n        {\\\"dbname\\\": \\\"aos_current_preview_20260927\\\"},\\n        {\\\"database\\\": \\\"aos_current_preview_20260927\\\"}))\\n    monkeypatch.setattr(gate, \\\"_runtime_file_dsns\\\", lambda *_a, **_k: ({\\n        plane: f\\\"host=localhost dbname=aos_meta_head user={plane}\\\"\\n        for plane in (\\\"directory\\\", \\\"runtime\\\", \\\"web\\\")}, [1, 2, 3, 4, 5]))\\n    monkeypatch.setattr(gate.psycopg, \\\"connect\\\", lambda *_a, **_k: pytest.fail(\\\"database connected\\\"))\\n    with pytest.raises(gate.HostPreflightBlocked, match=\\\"CREDENTIAL_DATABASE_DRIFT\\\"):\\n        gate.preflight(signed_receipt=Path(\\\"/signed\\\"), credential_file=Path(\\\"/protected/old.json\\\"))\\n\\n\\n@pytest.mark.parametrize(\\\"bad\\\", [\\n    identity(\\\"web\\\", 3, database=\\\"aos_meta_head\\\"),\\n    identity(\\\"runtime\\\", 2),\\n    identity(\\\"web\\\", 3, privileged=True),\\n])\\ndef test_mixed_same_role_or_privileged_identity_rejected(gate, bad):\\n    with pytest.raises(gate.HostPreflightBlocked, match=\\\"RUNTIME_IDENTITY_INVALID\\\"):\\n        gate.require_current_identities(\\n            directory=identity(\\\"directory\\\", 1, directory=True),\\n            runtime=identity(\\\"runtime\\\", 2, runtime=True), web=bad,\\n            authority=(\\\"172.0.0.2\\\", 5432, \\\"aos_current_preview_20260927\\\"),\\n        )\\n\\n\\nclass ReadConn:\\n    read_only = True\\n\\n    def __init__(self, assignment=None, candidates=None, enabled_bindings=0):\\n        self.assignment = assignment\\n        self.candidates = candidates\\n        self.enabled_bindings = enabled_bindings\\n        self.calls = []\\n\\n    def execute(self, query, params):\\n        self.calls.append((query, params))\\n        return self\\n\\n    def fetchone(self):\\n        if \\\"extension_runtime_binding\\\" in self.calls[-1][0]:\\n            return {\\\"enabled_bindings\\\": self.enabled_bindings}\\n        return self.assignment\\n\\n\\ndef test_exact_host_assignment_and_identity_required(gate, monkeypatch):\\n    monkeypatch.setattr(gate, \\\"read_candidates\\\", lambda *_: pytest.fail(\\\"candidates read too early\\\"))\\n    conn = ReadConn()\\n    with pytest.raises(gate.HostPreflightBlocked, match=\\\"HOST_ASSIGNMENT_MISSING\\\"):\\n        gate.require_current_host_and_candidates(conn, identity(\\\"directory\\\", 1, directory=True))\\n    assert conn.calls[0][1] == (\\\"org-org\\\", \\\"dev-project\\\")\\n\\n\\ndef test_host_identity_must_match_directory_role_and_oid(gate, monkeypatch):\\n    monkeypatch.setattr(gate, \\\"read_candidates\\\", lambda *_: pytest.fail(\\\"candidates read too early\\\"))\\n    conn = ReadConn({\\\"state\\\": \\\"assigned\\\", \\\"host_id\\\": \\\"host-1\\\", \\\"database_role\\\": \\\"old-dir\\\",\\n                     \\\"database_role_oid\\\": 99, \\\"enabled\\\": True})\\n    with pytest.raises(gate.HostPreflightBlocked, match=\\\"HOST_IDENTITY_MISMATCH\\\"):\\n        gate.require_current_host_and_candidates(conn, identity(\\\"directory\\\", 1, directory=True))\\n\\n\\ndef test_missing_configuration_candidates_fail_closed(gate, monkeypatch):\\n    from aos_api.extension_runtime.runtime_configuration_candidates import RuntimeConfigurationCandidates\\n    monkeypatch.setattr(gate, \\\"read_candidates\\\", lambda *_: RuntimeConfigurationCandidates(\\n        {\\\"budgets\\\": 0}, (\\\"budgets\\\",), False))\\n    conn = ReadConn({\\\"state\\\": \\\"assigned\\\", \\\"host_id\\\": \\\"host-1\\\", \\\"database_role\\\": \\\"directory\\\",\\n                     \\\"database_role_oid\\\": 1, \\\"enabled\\\": True})\\n    with pytest.raises(gate.HostPreflightBlocked, match=\\\"CONFIGURATION_CANDIDATES_MISSING\\\"):\\n        gate.require_current_host_and_candidates(co